<template><div class="page-hero"><div class="container"><p class="eyebrow">ORAL HEALTH NEWS</p><h1>口腔资讯</h1><p>由院方编辑发布口腔健康资讯，提供专业、清晰的健康知识参考。</p></div></div><section class="section"><div class="container"><form class="article-search" @submit.prevent="search"><label for="article-keyword">搜索口腔资讯</label><div><input id="article-keyword" v-model="keyword" type="search" placeholder="输入牙齿、种植、正畸等关键词" /><button class="button button-primary" type="submit">搜索</button></div></form><div v-if="loading" class="state-card">正在加载口腔资讯…</div><div v-else-if="error" class="state-card"><p>{{error}}</p><button class="button button-primary" @click="load">重新加载</button></div><div v-else-if="!result.list.length" class="state-card">暂未找到相关资讯，请更换关键词。</div><div v-else class="article-grid article-list-grid"><RouterLink v-for="article in result.list" :key="article.id" :to="`/articles/${article.slug}`" class="article-card"><div class="article-cover"><img v-if="article.coverUrl" :src="article.coverUrl" :alt="article.title" loading="lazy" /><span v-else>ORAL<br>NEWS</span></div><div class="article-body"><time>{{formatDate(article.publishedAt)}}</time><h2>{{article.title}}</h2><p>{{article.digest || '阅读专业、实用的口腔健康资讯。'}}</p></div></RouterLink></div><div v-if="result.total>result.pageSize" class="pagination"><button :disabled="page<=1" @click="go(page-1)">上一页</button><span>第 {{page}} 页</span><button :disabled="page*result.pageSize>=result.total" @click="go(page+1)">下一页</button></div></div></section></template>
<script setup lang="ts">import { onMounted,reactive,ref } from 'vue';import { RouterLink } from 'vue-router';import { Article,websiteApi } from '../api';import { formatDate } from '../site';const keyword=ref(''),page=ref(1),loading=ref(true),error=ref('');const result=reactive<{total:number;pageSize:number;list:Article[]}>({total:0,pageSize:12,list:[]});async function load(){loading.value=true;error.value='';try{const data=await websiteApi.articles(page.value,keyword.value);Object.assign(result,data);}catch(e){error.value=e instanceof Error?e.message:'口腔资讯加载失败';}finally{loading.value=false;}}function search(){page.value=1;void load();}function go(value:number){page.value=value;void load();window.scrollTo({top:0,behavior:'smooth'});}onMounted(load);</script>
